template <typename It, typename OtherIt>
struct RevIt {
    It current;
    using base_type = It;
    // std::reverse_iterator requires implicit conversions

    // Core comparison mechanism for RevIt::operator>=
    // Reverse logic: lhs >= rhs <=> lhs.base() <= rhs.base()

    friend bool operator>=(
        const RevIt<It>& lhs, const RevIt<OtherIt>& rhs)
    {
        // Compiler optimizes this comparison
        // based on underlying iterator category.
        return lhs.current <= rhs.current;
    }
};

// Optimization:
// If It == raw pointer (T*), the compiler generates
// (T* diff = base_b - base_a) followed by a sign check,
// utilizing fast subtraction/comparison assembly instructions
// instead of complex iterator logic.
